// src/components/Contacto.js
import React, { useState } from 'react';
import './Contacto.css';

const Contacto = () => {
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    mensaje: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Aquí se puede manejar el envío del formulario (ej. usando una API)
    alert('Formulario enviado');
  };

  return (
    <section id="contacto">
      <div className="contacto-content">
        <h2>Contacto</h2>
        <p>
          ¿Tienes alguna pregunta o necesitas más información? No dudes en ponerte en contacto con nosotros. Estaremos encantados de ayudarte.
        </p>

        <div className="contact-info">
          <div className="contact-item">
            <i className="fa-solid fa-phone"></i>
            <h3>Teléfono</h3>
            <p>+1 234 567 890</p>
          </div>
          <div className="contact-item">
            <i className="fa-solid fa-envelope"></i>
            <h3>Email</h3>
            <p>contacto@freetraders.com</p>
          </div>
          <div className="contact-item">
            <i className="fa-solid fa-location-dot"></i>
            <h3>Dirección</h3>
            <p>Calle Ficticia, 123, Ciudad, País</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="formulario">
          <h3>Envíanos un mensaje</h3>
          <input
            type="text"
            name="nombre"
            placeholder="Tu nombre"
            value={formData.nombre}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Tu correo electrónico"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <textarea
            name="mensaje"
            placeholder="Tu mensaje"
            value={formData.mensaje}
            onChange={handleChange}
            rows="4"
            required
          />
          <input type="submit" value="Enviar mensaje" />
        </form>
      </div>
    </section>
  );
};

export default Contacto;
